"Endless war: destroy the Swarm HQ and all its key buildings.":"முடிவற்ற போர்: திரளின் தலைமையகத்தையும் அதன் அனைத்து முக்கிய கட்டடங்களையும் தகர்ப்பீர்.",
"Match: 60 minutes. Destroy the Swarm HQ and all its key buildings — or hold more points at the end.":"ஆட்டம்: 60 நிமிடங்கள். திரளின் தலைமையகத்தையும் அதன் அனைத்து முக்கிய கட்டடங்களையும் தகர் — அல்லது இறுதியில் அதிகப் புள்ளிகளைப் பிடித்திரு.",
"\"◩ Strategy\" at the top right — top view, \"⇆\" — next unit, ☰ — everything else.":"மேல் வலதில் \"◩ போர்த்தந்திரம்\" — மேல்நோக்குக் காட்சி, \"⇆\" — அடுத்த அலகு, ☰ — மற்றவை அனைத்தும்.",
"\"◩ Strategy\" — top view; \"▶ Possess\" there — back to battle. X — quick unit switch.":"\"◩ போர்த்தந்திரம்\" — மேல்நோக்குக் காட்சி; அங்குள்ள \"▶ கட்டுப்படுத்து\" — மீண்டும் போருக்கு. X — அலகை விரைவாக மாற்று.",
"Tab — strategy; in strategy Tab possesses the selected unit. X — quick unit switch.":"Tab — போர்த்தந்திரம்; போர்த்தந்திரத்தில் Tab தேர்ந்த அலகைக் கட்டுப்படுத்தும். X — அலகை விரைவாக மாற்று.",
