"Select the HQ and train a builder (50 ore)":"தலைமையகத்தைத் தேர்ந்து கட்டுநரைப் பயிற்றுவி (50 தாது)",
"The limit depends on \"Battle scale\" in the settings":"வரம்பு அமைப்புகளிலுள்ள \"ஆட்டத்தின் அளவு\"-ஐப் பொறுத்தது",
