"Wait or cancel an order (RMB on the button or click the building queue)":"காத்திரு அல்லது ஆணையை ரத்துசெய் (பொத்தானில் வலது சொடுக்கு அல்லது கட்டட வரிசையைச் சொடுக்கு)",
"Army limits depend on \"Battle scale\" in the settings":"படை வரம்புகள் அமைப்புகளிலுள்ள \"ஆட்டத்தின் அளவு\"-ஐப் பொறுத்தவை",
