"Buildings are built by <b>builders</b>: pick a building → LMB on a spot. The selected or nearest idle builder goes. <kbd>.</kbd> — idle builder.":"கட்டடங்களை <b>கட்டுநர்கள்</b> கட்டுவர்: கட்டடத்தைத் தேர்ந்து → இடத்தில் இடது சொடுக்கு. தேர்ந்த அல்லது அருகிலுள்ள ஓய்வான கட்டுநர் செல்வார். <kbd>.</kbd> — ஓய்வான கட்டுநர்.",
