"Core":"மையக்கரு",
"Also: wrecks of destroyed enemies, first-expedition depots and crystals (shoot them) give one-off ore.":"மேலும்: அழிந்த எதிரிகளின் சிதைவுகள், முதல் பயணக்குழுவின் கிடங்குகள், படிகங்கள் (சுட்டு உடை) ஒருமுறை தாது தரும்.",
" Battle scale: income ×{0}.":" ஆட்டத்தின் அளவு: வருமானம் ×{0}.",
"How to speed it up":"எப்படி விரைவுபடுத்துவது",
"With a builder (<kbd>.</kbd> to find one, you have {0}) build an <b>extractor</b> <kbd>C</kbd> on a glowing ⛏ vein. Safest are at the base, plus one at every point.":"கட்டுநரால் (<kbd>.</kbd> — தேட, இப்போது {0}) ஒளிரும் ⛏ நரம்பில் <b>பிரித்தெடுப்பான்</b> <kbd>C</kbd> கட்டு. தளத்தருகே உள்ளவை பாதுகாப்பானவை, ஒவ்வொரு புள்ளியிலும் ஒன்று கூடுதல்.",
"Capture and hold points — each pays income and opens its vein.":"புள்ளிகளைக் கைப்பற்றிப் பிடித்திரு — ஒவ்வொன்றும் வருமானம் தந்து தன் நரம்பைத் திறக்கும்.",
"Research \"Deep drilling\" at the HQ: +35% extractor output per level.":"தலைமையகத்தில் \"ஆழ்துளையிடல்\" ஆராய்: நிலைக்கு பிரித்தெடுப்பான் விளைச்சல் +35%.",
"Protect builders and extractors: the Swarm hunts them. A turret next to a vein pays off.":"கட்டுநர்களையும் பிரித்தெடுப்பான்களையும் காத்திடு: திரள் அவற்றை வேட்டையாடும். நரம்பருகே ஒரு சிறு கோபுரம் பலனளிக்கும்.",
"Ore is spent on troops, buildings, squad reinforcements (18 per trooper) and drop pods.":"தாது படைகள், கட்டடங்கள், அணி வலுவூட்டல் (வீரருக்கு 18), இறங்கு கலங்களுக்குச் செலவாகும்.",
"Tap a spot on the ground first":"முதலில் தரையில் ஓர் இடத்தைத் தட்டு",
