"Jet leap":"ஜெட்பேக் பாய்ச்சல்",
"The squad jet-leaps to a point (up to 80 m).":"படைப்பிரிவு ஜெட்பேக்குகளில் புள்ளிக்குப் பாயும் (80 மீ வரை).",
"Suppress":"அடக்குதல்",
"Saturating fire: enemies in the area are slowed and miss.":"பரப்பளவில் துப்பாக்கிச் சூட்டுப் பொழிவு: பகுதியிலுள்ள எதிரிகள் மெதுவாகி குறி தவறுவர்.",
"Repair":"பழுதுபார்ப்பு",
"Nanobots repair every trooper in the squad.":"நானோ ரோபோக்கள் படைப்பிரிவின் ஒவ்வொரு வீரரையும் சரிசெய்யும்.",
"Barrage":"சரமாரி",
