"Orbital strike":"சுற்றுப்பாதைத் தாக்குதல்",
"An orbital beam burns the area. Wrecks buildings.":"சுற்றுப்பாதைக் கதிர் அந்தப் பகுதியை எரிக்கிறது. கட்டடங்களை அழிக்கும்.",
"Too far from your forces":"உங்கள் படைகளிடமிருந்து மிகத் தொலைவில் உள்ளது",
"WARNING: enemy strike incoming on your area!":"எச்சரிக்கை: உங்கள் பகுதியில் எதிரித் தாக்குதல் வருகிறது!",
"Warning! Strike incoming on our position":"எச்சரிக்கை! நம் நிலைமீது தாக்குதல் வருகிறது",
