" It's far — {0} for a drop pod.":" தொலைவு — {0}, இறங்கு கலம் தேவை.",
"Belay that! ":"நிறுத்து! ",
"{0}, hostiles {1}, {2} meters. {3} {4}. Take them out!":"{0}, எதிரி {1}, {2} மீட்டர். {3} {4}. அழியுங்கள்!",
"{0}, too many of them head-on. Flank along the marker, then open fire!":"{0}, நேரடியாக அவர்கள் மிக அதிகம். குறிப்பான் வழியாகப் பக்கவாட்டில் சுற்றிச் சென்று, பிறகு சுடுங்கள்!",
"{0}, large enemy force {1}. Don't engage — go around them via the marker.":"{0}, எதிரியின் பெரும்படை {1}. மோதாதீர்கள் — குறிப்பான் வழியாகச் சுற்றிச் செல்லுங்கள்.",
"{0}, enemy tank {1}! Rockets — Q. Destroy it!":"{0}, எதிரிப் பீரங்கி வண்டி {1}! ராக்கெட்டுகள் — Q. அழியுங்கள்!",
"{0}, enemy tank {1}, {2} meters. Duel — destroy it!":"{0}, எதிரிப் பீரங்கி வண்டி {1}, {2} மீட்டர். சண்டை — அழியுங்கள்!",
"{0}, {1} {2} is pinning us. Destroy it — rockets and grenades!":"{0}, {1} {2} நம்மை முடக்குகிறது. அழியுங்கள் — ராக்கெட்டுகள், கையெறி குண்டுகள்!",
"{0}, you are badly damaged. Fall back to the marker for repairs!":"{0}, நீங்கள் மோசமாகச் சேதமடைந்துள்ளீர்கள். பழுதுபார்க்கக் குறிப்பானுக்குப் பின்வாங்குங்கள்!",
"{0}, a Swarm squad is coming {1}, {2} meters. Ambush: take the marked position and greet them!":"{0}, திரள் படைப்பிரிவு {1} வருகிறது, {2} மீட்டர். பதுங்கல்: குறிப்பான் அருகே நிலை எடுத்து வரவேற்கத் தயாராகுங்கள்!",
"{0}, Swarm squad {1}, {2} meters. Intercept!":"{0}, திரள் படைப்பிரிவு {1}, {2} மீட்டர். இடைமறியுங்கள்!",
"{0}, Swarm signaller {1}, {2} meters! Kill it before it calls a drop!":"{0}, திரள் சமிக்ஞையாளர் {1}, {2} மீட்டர்! இறக்கத்தை அழைப்பதற்கு முன் கொல்லுங்கள்!",
"{0}, Swarm drone {1}, {2} meters. Shoot it down!":"{0}, திரள் ட்ரோன் {1}, {2} மீட்டர். சுட்டு வீழ்த்துங்கள்!",
"{0}, {1} {2}, {3} meters. Destroy it — rockets, {4}!":"{0}, {1} {2}, {3} மீட்டர். அழியுங்கள் — ராக்கெட்டுகள், {4}!",
"{0}, {1} is moving into the fight {2}. Cover it!":"{0}, {1} சண்டைக்குச் செல்கிறது {2}. காப்பு கொடுங்கள்!",
"{0}, {1} is close, {2} meters. Capture it!":"{0}, {1} அருகில், {2} மீட்டர். கைப்பற்றுங்கள்!",
