"Fast buggy: a 4-rocket salvo and an MG. Hunts builders and harvesters, flanks. Fragile.":"வேகமான பக்கி: 4 ராக்கெட் தொடர்வீச்சும் இயந்திரத் துப்பாக்கியும். கட்டுநர்களையும் தாது எடுப்பவர்களையும் வேட்டையாடி, பக்கவாட்டில் சுற்றும். நொறுங்கக்கூடியது.",
