"Wait up!":"எங்களுக்காகக் காத்திரு!",
"Congrats on the promotion!":"பதவி உயர்வுக்கு வாழ்த்துகள்!",
"New stripes suit you!":"புதிய கோடுகள் உனக்குப் பொருந்துகின்றன!",
"Pod inbound! Reinforcements!":"கலம் வருகிறது! உதவிப்படை!",
"Anyone remember why the sky is a portal?":"வானம் ஏன் ஒரு வாயில் என்று யாருக்காவது நினைவிருக்கிறதா?",
"They say if you jump in the shaft you pop out at the enemy's. Not testing it.":"தண்டுக்குள் குதித்தால் எதிரியிடம் வெளிவருவோம் என்கிறார்கள். சோதிக்க மாட்டேன்.",
"The Swarm painted their visors red again. Show-offs.":"திரள் மீண்டும் தம் கண்ணாடிகளுக்குச் சிவப்பு வண்ணம் பூசிவிட்டது. பகட்டுக்காரர்கள்.",
"Ore, ore… when do we get some oil?":"தாது, தாது… எண்ணெய் எப்போது தருவார்கள்?",
"I dreamt I was a toaster. It was peaceful.":"நான் ஒரு டோஸ்டர் என்று கனவு கண்டேன். அமைதியாக இருந்தது.",
"Quiet. Too quiet.":"அமைதி. மிக அதிகமான அமைதி.",
"See that? Our base is above the Swarm base again. Portals, man.":"பார்த்தீர்களா? திரள் தளத்துக்கு மேலே மீண்டும் நம் தளம். வாயில்கள், நண்பா.",
"Diman, if you're reading this — we need a vacation.":"திமான், இதைப் படித்தால் — நமக்கு விடுமுறை வேண்டும்.",
