"Only builders build. No builder selected — the button picks the nearest idle one and starts the blueprint; then LMB on a spot.":"கட்டுநர் மட்டுமே கட்டுவார். கட்டுநர் தேர்வில்லையெனில் பொத்தான் அருகிலுள்ள ஓய்வு கட்டுநரைத் தேர்ந்து வரைபடத்தைத் தொடங்கும்; பின் இடத்தில் இடது சொடுக்கு.",
"Pick a power, then click the target":"ஒரு தாக்குதலைத் தேர்ந்தெடு, பிறகு இலக்கைச் சொடுக்கு",
"Controls":"கட்டுப்பாடுகள்",
"All strategy keys":"அனைத்து போர்த்தந்திர விசைகள்",
"On — builds the base, orders troops and gives orders by itself (your orders take priority). Off — you do everything.":"இயக்கத்தில் — தளத்தைக் கட்டி, படைகளை உருவாக்கி, கட்டளைகளையும் தானே வழங்கும் (உன் கட்டளைகளுக்கே முன்னுரிமை). நிறுத்தத்தில் — எல்லாவற்றையும் நீயே செய்கிறாய்.",
"Auto-build on: the strategist builds the base with builders":"தானியங்கிக் கட்டுமானம் இயக்கத்தில்: போர்த்தந்திரவாதி கட்டுநர்களால் தளத்தைக் கட்டுகிறார்",
"Auto-build off: only you build":"தானியங்கிக் கட்டுமானம் நிறுத்தத்தில்: கட்டடங்களை நீ மட்டுமே கட்டுவாய்",
"picks nearest builder":"அருகிலுள்ள கட்டுநரைத் தேர்ந்தெடுக்கும்",
"takes a busy builder":"வேலையிலுள்ள கட்டுநரை எடுக்கும்",
"waiting for ore":"தாதுவுக்காகக் காத்திருக்கிறது",
"Auto-build":"தானியங்கிக் கட்டுமானம்",
"The strategist builds buildings and extractors with its builders (when the AI strategist is on). Your orders to builders take priority.":"AI போர்த்தந்திரவாதி இயக்கத்தில் இருக்கும்போது, கட்டுநர்களைக் கொண்டு கட்டடங்களையும் பிரித்தெடுப்பான்களையும் அதுவே கட்டும். கட்டுநர்களுக்கான உன் கட்டளைகளுக்கே முன்னுரிமை.",
"troopers":"வீரர்கள்",
"Selected":"தேர்ந்தெடுத்தவை",
"Click — select only it · Shift — remove · double — camera":"சொடுக்கு — அதை மட்டும் தேர்ந்தெடு · Shift — நீக்கு · இரட்டை — கேமரா",
"enemy":"எதிரி",
"Click — cancel (ore refunded)":"சொடுக்கு — ரத்துசெய் (தாது திரும்பும்)",
"Tap — select · long tap — order · double tap — possess · drag — camera, pinch — zoom":"தட்டு — தேர்ந்தெடு · நீண்ட தட்டு — கட்டளை · இரட்டைத் தட்டு — கட்டுப்படுத்து · வருடு — கேமரா, இரு விரல் — அளவு",
"LMB — select · drag — box · RMB — order · double-click — possess · Ctrl+1…9 — group":"இடது சொடுக்கு — தேர்ந்தெடு · சட்டம் — பலவற்றை · வலது சொடுக்கு — கட்டளை · இரட்டைச் சொடுக்கு — கட்டுப்படுத்து · Ctrl+1…9 — குழு",
