"attack-move ⚔ (stop and fight on contact, then continue) · on an enemy — attack · on a point — capture":"தாக்குதல் நகர்வு ⚔ (எதிரியைக் கண்டதும் நின்று போரிட்டு, பிறகு தொடரும்) · எதிரி மீது — தாக்கு · புள்ளி மீது — கைப்பற்று",
"march » — run without stopping, firing on the move":"அணிவகுப்பு » — நிற்காமல் ஓடி, ஓடியபடியே சுடும்",
"(hold) labels on all units":"(பிடித்திரு) அனைத்து அலகுகளின் பெயர்ச்சீட்டுகள்",
"double-click":"இரட்டைச் சொடுக்கு",
"possess":"கட்டுப்படுத்து",
"abilities":"திறன்கள்",
"build: turret, AA, extractor, outpost, factory, hub, airdock (a builder builds; none selected — the nearest is picked)":"கட்டுமானம்: சுடுகோபுரம், வான்தடுப்புத் துப்பாக்கி, பிரித்தெடுப்பான், புறக்காவல் நிலையம், ஆலை, ட்ரோன் மையம், வான்தளம் (கட்டுநர் கட்டுவார்; யாரும் தேர்வாகாவிட்டால் அருகிலுள்ளவர்)",
"idle builder":"சும்மா உள்ள கட்டுநர்",
"cancel construction (refund)":"கட்டுமானத்தை ரத்துசெய் (தாது திரும்பும்)",
