"sky assault":"வான்வழி இறக்கம்",
"groups":"குழுக்கள்",
"whole army":"முழுப் படை",
"jump to last alert":"கடைசி எச்சரிக்கைக்குச் செல்",
"to base":"தளத்துக்கு",
"possess the selection (nothing selected — to battle)":"தேர்ந்தெடுத்ததைக் கட்டுப்படுத்து (எதுவும் இல்லையெனில் — போருக்கு)",
"retreat to base":"தளத்துக்குப் பின்வாங்கு",
"buttons of the Units/Tech/Powers tabs on the right":"வலப்புறம் உள்ள படைகள்/மேம்பாடுகள்/தாக்குதல்கள் தாவல் பொத்தான்கள்",
"panel tabs":"பலகைத் தாவல்கள்",
"minimap":"சிறுவரைபடம்",
"click/drag — camera, RMB — order":"சொடுக்கு/இழு — கேமரா, வலது சொடுக்கு — கட்டளை",
"NORTH · US":"வடக்கு · நாம்",
"SOUTH · SWARM":"தெற்கு · திரள்",
"Attack-move":"தாக்கியபடி செல்",
"Then click (tap) the ground: they move and fight on the way. On an enemy — attack it. Same as RMB.":"பிறகு தரையைச் சொடுக்கு (தட்டு): நகர்ந்தபடியே போரிடுவார்கள். எதிரி மீது — அவனைத் தாக்கு. வலது சொடுக்கும் இதே.",
"Run":"ஓட்டம்",
"Then click (tap) the ground: they run without engaging. Same as double RMB.":"பிறகு தரையைச் சொடுக்கு (தட்டு): மோதாமல் ஓடுவார்கள். இரட்டை வலது சொடுக்கும் இதே.",
"2×RMB":"2×வலது சொடுக்கு",
"Selected groups stay put and return fire.":"தேர்ந்தெடுத்தவர்கள் இருந்த இடத்திலேயே நின்று பதிலடி கொடுப்பார்கள்.",
"Retreat":"பின்வாங்கு",
"Run back to the HQ (or nearest outpost) without engaging.":"மோதாமல் தலைமையகத்துக்கு (அல்லது அருகிலுள்ள புறக்காவல் நிலையத்துக்கு) ஓடிவிடு.",
"Squads jet up through the dome portal and land at the enemy.":"படைப்பிரிவுகள் ஜெட்பேக்கில் எழுந்து கூம்பு வாயிலைக் கடந்து எதிரியிடம் இறங்கும்.",
"Control the selected trooper, tank or turret yourself. The same key in battle brings you back to strategy.":"தேர்ந்தெடுத்த வீரர், பீரங்கி வண்டி அல்லது சுடுகோபுரத்தை நீயே இயக்கு. போரில் இதே விசை உன்னைப் போர்த்தந்திரத்துக்குத் திருப்பும்.",
"4 troopers: assault, heavy gunner, rocketeer, medic.":"4 வீரர்கள்: தாக்குதல் வீரர், கனரக துப்பாக்கி வீரர், ராக்கெட் வீரர், மருத்துவர்.",
"Autonomous combat vehicle: cannon and MG, barrage, smoke, overdrive.":"தானியங்கிப் போர் வாகனம்: பீரங்கியும் இயந்திரத் துப்பாக்கியும், அடுக்குத் தாக்குதல், புகை, அதிவேகம்.",
"Fast flying gunner, good against infantry.":"வேகமான பறக்கும் துப்பாக்கி வீரர், காலாட்படைக்கு எதிராக நன்று.",
"Elite squad with strong jetpacks — can sky-assault through the dome.":"வலிமையான ஜெட்பேக்குகளுடன் தேர்ந்த படைப்பிரிவு — கூம்பு வழியாக வான்வழி இறங்கலாம்.",
"A lone railgun sniper.":"தனி ரயில்துப்பாக்கிக் குறிசுடு வீரர்.",
"Fast scout: sees far and spots enemies.":"வேகமான உளவாளி: தூரம் பார்ப்பான், எதிரிகளைக் காட்டுவான்.",
"A squad drops from orbit right at the front line.":"படைப்பிரிவு சுற்றுப்பாதையிலிருந்து நேரே முன்னணியில் இறங்கும்.",
"Jetpacks II: infantry reaches the dome and can sky-assault.":"ஜெட்பேக் II: காலாட்படை கூம்பை எட்டி வான்வழி இறங்கலாம்.",
"+armor for the whole army (3 levels).":"முழுப் படைக்கும் +கவசம் (3 நிலைகள்).",
"+damage for the whole army (3 levels).":"முழுப் படைக்கும் +சேதம் (3 நிலைகள்).",
