"Mouse: LMB — fire, RMB — aim, Shift — jetpack. Tank: LMB — cannon, RMB — MG. M — sound, O — quality, Esc — menu.":"சுட்டி: இடது சொடுக்கு — சுடு, வலது சொடுக்கு — குறிபார், Shift — ஜெட்பேக். பீரங்கி வண்டி: இடது சொடுக்கு — பீரங்கி, வலது சொடுக்கு — இயந்திரத் துப்பாக்கி. M — ஒலி, O — தரம், Esc — பட்டியல்.",
"Reset to defaults":"இயல்புநிலைக்கு மீட்டமை",
"Test: press keys and mouse buttons":"சோதனை: விசைகளையும் சுட்டிப் பொத்தான்களையும் அழுத்து",
"Battle saved: ":"போர் சேமிக்கப்பட்டது: ",
"Save failed":"சேமிக்க முடியவில்லை",
"SMG":"சிறு தானியங்கித் துப்பாக்கி",
