"Turret MG":"கோபுர இயந்திரத் துப்பாக்கி",
"Extended mag":"நீட்டிக்கப்பட்ட தோட்டாப்பெட்டி",
"Compensator":"பின்னுதைப்புத் தணிப்பான்",
