"Rapid bolt":"விரைவு பூட்டி",
"Jet dash (or double-tap jetpack in the air)":"ஜெட்பேக் பாய்ச்சல் (அல்லது காற்றில் இரு முறை ஜெட்பேக்)",
"SIGNAL TRANSFER":"சமிக்ஞை மாற்றம்",
"low ammo":"தோட்டா குறைவு",
"EMPTY — {0}":"காலி — {0}",
"Simple fire: aim at an enemy and it fires. ◎ — aim, ⟳ — reload":"எளிய சுடுதல்: எதிரியைக் குறிவை, தானே சுடும். ◎ — குறிபார், ⟳ — மறுநிரப்பு",
"● — fire, ◎ — aim, ⟳ — reload":"● — சுடு, ◎ — குறிபார், ⟳ — மறுநிரப்பு",
"◎ — aim, R — reload, » — jet dash":"◎ — குறிபார், R — மறுநிரப்பு, » — ஜெட்பேக் பாய்ச்சல்",
"RMB — aim · {0} — reload · {1} standing — crouch · {2} or 2×{3} in the air — dash":"வலது சொடுக்கு — குறிபார் · {0} — மறுநிரப்பு · நின்றபடி {1} — குனி · {2} அல்லது காற்றில் 2×{3} — பாய்ச்சல்",
"Track another objective":"வேறு இலக்கைக் கண்காணி",
"Orders ↔ free play":"கட்டளைகள் ↔ செயல் சுதந்திரம்",
"Squad with me ↔ going solo":"படைப்பிரிவு என்னுடன் ↔ தனியாகச் செயல்படுதல்",
"Redeploy: pod to objective / into the fight":"இடமாற்றம்: கலம் இலக்கிற்கு / சண்டையின் நடுவில்",
"The objective is far. {0} — drop pod straight to it (with your squad). Shift+{1} — possess a trooper in the thick of the fight.":"இலக்கு தொலைவில் உள்ளது. {0} — கலத்தில் நேராக இலக்கிற்கு (உன் படைப்பிரிவுடன்). Shift+{1} — சண்டையின் நடுவில் உள்ள வீரரைக் கட்டுப்படுத்து.",
"Intel: a Swarm squad is heading your way — {0}, about {1} meters.":"உளவு: திரள் படைப்பிரிவு உங்களை நோக்கி வருகிறது — {0}, சுமார் {1} மீட்டர்.",
"Contact from above! A Swarm pod is coming down {0}, {1} meters!":"மேலிருந்து தொடர்பு! திரள் கலம் {0} பக்கம் இறங்குகிறது, {1} மீட்டர்!",
"Swarm signaller {0}! It will call a drop in 12 seconds — kill it first!":"திரள் சமிக்ஞையாளர் {0}! 12 வினாடியில் படையிறக்கம் அழைப்பான் — முதலில் அவனைக் கொல்!",
"Signaller down — no drop.":"சமிக்ஞையாளர் வீழ்ந்தான் — படையிறக்கம் இல்லை.",
"The signaller got it off! Swarm pod inbound.":"சமிக்ஞையாளர் அழைத்துவிட்டான்! திரள் கலம் நெருங்குகிறது.",
"The Swarm is counter-attacking {0}! Get ready to defend.":"திரள் {0}-ஐ எதிர்த்தாக்குகிறது! தற்காப்புக்குத் தயாராகுங்கள்.",
"You're going solo. {0} returns to the strategist. {1} — call them back.":"தனியாகச் செயல்படுகிறாய். {0} போர்த்தந்திரவாதி கட்டளைக்குச் செல்கிறது. {1} — மீண்டும் அழை.",
"No free squads nearby — you stay solo for now.":"அருகில் ஒதுக்கப்படாத படைப்பிரிவுகள் இல்லை — தற்போது தனியாக இருக்கிறாய்.",
"{0}: on our way to you, commander!":"{0}: உன்னிடம் வருகிறோம், தளபதி!",
"{0} is with you again.":"{0} மீண்டும் உன்னுடன்.",
"Mode: going solo":"பயன்முறை: தனியாகச் செயல்படுதல்",
"Mode: squad with me":"பயன்முறை: படைப்பிரிவு என்னுடன்",
"Understood, you call the shots. I will only show quiet suggestions.":"புரிந்தது, நீயே முடிவெடு. குறிப்புகளைக் குரலின்றி மட்டும் தருவேன்.",
"Copy. Back to giving you orders.":"சரி. மீண்டும் கட்டளைகள் தருகிறேன்.",
"Mode: free play ({0})":"பயன்முறை: சுதந்திரம் ({0})",
