"SAVES":"சேமிப்புகள்",
"Saves live only in this browser on this device (localStorage). Anyone else who downloads the game gets none of your saves. To move a battle to another computer or browser: \"Export to file\" here → \"Import from file\" there. Autosave runs every 3 minutes of battle and when you quit to the menu.":"சேமிப்புகள் இந்தச் சாதனத்தின் இந்த உலாவியில் மட்டுமே (localStorage) இருக்கும். வேறொருவர் ஆட்டத்தைப் பதிவிறக்கினால் உன் சேமிப்புகள் அவரிடம் இருக்காது. போரை வேறு கணினிக்கோ உலாவிக்கோ மாற்ற: இங்கே «கோப்பாக ஏற்றுமதி செய்» → அங்கே «கோப்பிலிருந்து இறக்குமதி». தானியங்கிச் சேமிப்பு ஒவ்வொரு 3 நிமிடப் போருக்கும், பட்டியலுக்கு வெளியேறும்போதும் நடக்கும்.",
"Import from file…":"கோப்பிலிருந்து இறக்குமதி…",
"Paste save text":"சேமிப்பு உரையை ஒட்டு",
"Import this text":"இந்த உரையை ஏற்று",
