"If no file appeared (e.g. the game runs inside claude.ai), press \"Copy text\" and paste it into any .json or .txt file.":"கோப்பு தோன்றவில்லை என்றால் (எ.கா. ஆட்டம் claude.ai உள்ளே ஓடினால்), «உரையை நகலெடு» அழுத்தி எந்த .json அல்லது .txt கோப்பிலும் ஒட்டு.",
"Could not read the file":"கோப்பைப் படிக்க முடியவில்லை",
