"Grenade: hold G to see the arc and blast circle; drag on the button to aim; release to throw.":"கையெறி குண்டு: G பிடி — வளைவும் வெடிப்பு வட்டமும் தெரியும்; பொத்தான் மீது விரலை இழு — கோணம்; விடு — எறி.",
"Grenade: hold {0} for the arc and blast circle, release to throw. Range — by view angle, wheel — power, RMB — underhand.":"கையெறி குண்டு: வளைவும் வெடிப்பு வட்டமும் காண {0} பிடி, எறிய விடு. தூரம் — பார்வைக் கோணத்தால், சக்கரம் — வலிமை, வலது சொடுக்கு — காலடியில்.",
"Grenades: hold G for the flight arc, blast point and radius, distance; release to throw. Range by view angle, wheel — power, RMB — underhand":"கையெறி குண்டுகள்: பறப்பு வளைவு, வெடிப்புப் புள்ளி, வட்டம், தூரம் காண G பிடி; எறிய விடு. தூரம் பார்வைக் கோணத்தால், சக்கரம் — வலிமை, வலது சொடுக்கு — காலடியில்",
"Grenades bounce and roll down slopes, 2.5 s fuse; 2 grenades, 9 s recharge; warning icon for enemy grenades nearby":"கையெறி குண்டு துள்ளி சரிவில் உருளும், 2.5 வினாடியில் வெடிக்கும்; 2 குண்டுகள், 9 வினாடி மீட்பு; அருகில் எதிரி குண்டு இருந்தால் எச்சரிக்கைச் சின்னம்",
"Grenade: hold — arc and blast point, release — throw · tank overdrive":"கையெறி குண்டு: பிடி — வளைவும் வெடிப்புப் புள்ளியும், விடு — எறி · டாங்க் முடுக்கம்",
"G — hold: see the arc and blast circle, release to throw. 2.5 s fuse, 2 grenades.":"G — பிடி: வளைவும் வெடிப்பு வட்டமும் தெரியும், விடு — எறி. 2.5 வினாடியில் வெடிக்கும், 2 குண்டுகள்.",
"Grenade ({0}): hold — flight arc, blast point and radius, distance; release — throw; a quick tap throws at once. Range by view angle, wheel — power, RMB — underhand. Phone: hold G and drag.":"கையெறி குண்டு ({0}): பிடி — பறப்பு வளைவு, வெடிப்புப் புள்ளியும் வட்டமும், தூரம்; விடு — எறி; சிறு தட்டு உடனே எறியும். தூரம் பார்வைக் கோணத்தால், சக்கரம் — வலிமை, வலது சொடுக்கு — காலடியில். கைபேசி: G பிடித்து விரலை இழு.",
