"Each level costs more than the last; every 50 levels — \"Veteran ★\". XP comes from everything: combat, orders, medals, contracts.":"ஒவ்வொரு நிலையும் முந்தையதை விட செலவு மிக்கது; ஒவ்வொரு 50 நிலைக்கும் — \"அனுபவசாலி ★\". அனுபவம் எல்லாவற்றிலும் கிடைக்கும்: சண்டை, கட்டளைகள், பதக்கங்கள், ஒப்பந்தங்கள்.",
