"Swipe up — grenade at target":"மேலே வருடு — இலக்கை நோக்கி கையெறி குண்டு",
"Pinch — grenade / rocket / zoom":"இருவிரல் சேர் — கையெறி குண்டு / ராக்கெட் / பெரிதாக்கு",
"Double tap right — reflex":"வலப்புறம் இருமுறை தட்டு — அனிச்சை",
"Tap — select, tap again — order":"தட்டு — தேர்வு, மீண்டும் தட்டு — கட்டளை",
"Hold — command menu, hold and drag — box":"பிடி — கட்டளை பட்டியல், பிடித்து இழு — சட்டம்",
"Pinch — zoom, twist — rotate":"இருவிரல் சேர் — அளவு, திருகு — சுழற்று",
"Show / hide the secondary HUD":"இரண்டாம்நிலை HUD-ஐக் காட்டு / மறை",
"Minimap: show / hide (tap the map to jump there)":"சிறுவரைபடம்: காட்டு / மறை (வரைபடத்தைத் தட்டினால் அங்கே தாவும்)",
