" · AI drives vehicles, E next to one — man its gun":" · வாகனத்தை AI ஓட்டும், அருகில் E — அதன் துப்பாக்கியைக் கையாள்",
"Possess squads (infantry)":"படைப்பிரிவுகளைக் கட்டுப்படுத்து (காலாட்படை)",
"Possess vehicles and drones":"வாகனங்களையும் ட்ரோன்களையும் கட்டுப்படுத்து",
"On the gun: {0}. The AI drives, you shoot. {1} — get off":"துப்பாக்கியில்: {0}. AI ஓட்டுகிறது, நீ சுடு. {1} — இறங்கு",
"The vehicle is destroyed — you jumped off":"வாகனம் அழிக்கப்பட்டது — நீ குதித்து இறங்கினாய்",
"{0} — get off the gun":"{0} — துப்பாக்கியிலிருந்து இறங்கு",
"{0} — man the gun: {1}":"{0} — துப்பாக்கியில் அமர்: {1}",
"Combo ×{0} · reflex +{1}%":"காம்போ ×{0} · அனிச்சை +{1}%",
"Strategist: troopers dropping to you — +{0} (−{1} ore)":"போர்த்தந்திரவாதி: உன்னிடம் வீரர்கள் இறங்குகிறார்கள் — +{0} (−{1} தாது)",
"Hold on, sending troopers your way":"தாக்குப்பிடி, உன்னிடம் வீரர்களை அனுப்புகிறேன்",
"· basic{0}":"· அடிப்படை{0}",
"· advanced":"· மேம்பட்ட",
"· rare":"· அரிய",
"Advanced: class order":"மேம்பட்டவை: வகை வரிசை",
"Voice of hints and curator":"குறிப்புகள் மற்றும் வழிகாட்டியின் குரல்",
"Advanced: custom class order":"மேம்பட்டவை: தனிப்பயன் வகை வரிசை",
"Voice of hints & curator":"குறிப்புகள் & வழிகாட்டியின் குரல்",
"Phone: three stick modes. Left only — \"auto\" (strong magnet, weaker bullets). Right only — aiming turns on by itself, stronger magnet, better accuracy. Both — no aiming, weaker magnet and accuracy. The 👁 button on the right hides/returns the HUD.":"கைபேசி: மூன்று குச்சி முறைகள். இடது மட்டும் — \"தானியங்கி\" (வலுவான காந்தம், பலவீனமான குண்டுகள்). வலது மட்டும் — குறி தானாக இயங்கும், வலுவான காந்தம், துல்லியம் அதிகம். இரண்டும் — குறி இல்லை, காந்தமும் துல்லியமும் குறைவு. வலப்புற 👁 பொத்தான் HUD-ஐ மறைக்கும்/மீட்கும்.",
"Phone: strategy simplified — engineer and buildings only. Cards on the left (engineer, HQ, barracks…): tap — the camera flies there, the bottom bar shows what to build/produce. \"To battle\" — top left. The army fights by itself. Full strategy — Settings → Phone.":"கைபேசி: போர்த்தந்திரம் எளிமையாக்கப்பட்டது — பொறியாளர் மற்றும் கட்டடங்கள் மட்டும். இடப்பக்கம் அட்டைகள் (பொறியாளர், தலைமையகம், படைவீடு…): தட்டு — கேமரா அங்கே பறக்கும், கீழ்ப்பட்டையில் எதைக் கட்டுவது/உற்பத்தி செய்வது என்று தெரியும். \"போருக்கு\" — மேல் இடது. படை தானாகப் போரிடும். முழுப் போர்த்தந்திரம் — அமைப்புகள் → கைபேசி.",
"Possession — two switches: \"Squads\" and \"Vehicles\" (vehicles are off by default on phones — the AI drives them). With vehicles off, E (phone: the button on the right) next to a friendly vehicle — man its gun: it drives itself, you shoot. The old custom class order is under \"Advanced\". A unit answers on the radio when you possess it.":"கட்டுப்படுத்துதல் — இரு சுவிட்சுகள்: \"படைப்பிரிவுகள்\" மற்றும் \"வாகனங்கள்\" (கைபேசியில் வாகனங்கள் இயல்பாக அணைவு — AI ஓட்டும்). வாகனங்கள் அணைந்திருந்தால், நட்பு வாகனம் அருகில் E (கைபேசியில் — வலப்புற பொத்தான்) — அதன் துப்பாக்கியில் அமர்: வாகனம் தானாகச் செல்லும், நீ சுடு. பழைய தனிப்பயன் வகை வரிசை \"மேம்பட்டவை\"யில் உள்ளது. கட்டுப்படுத்தும்போது அலகு வானொலியில் பதிலளிக்கும்.",
"Smart hints: basic hints switch off after the 2nd launch, but the game still points out a feature you never use. Switches: basic / advanced / rare, and a separate one for the voice of hints and curator.":"புத்திசாலிக் குறிப்புகள்: அடிப்படைக் குறிப்புகள் 2-ஆம் தொடக்கத்துக்குப் பின் தானாக அணையும், ஆனால் நீ பயன்படுத்தாத வசதியை விளையாட்டு சுட்டிக்காட்டும். சுவிட்சுகள்: அடிப்படை / மேம்பட்ட / அரிய, மேலும் குறிப்புகள் மற்றும் வழிகாட்டியின் குரலுக்குத் தனியாக.",
"Reflex charges from kills (streaks charge more). Squadmates fell behind or died — the strategist drops new ones to you (pricier than normal reinforcement). The v7.2gfx graphics and sound are merged in: billowing explosions, smoke, debris, shaft and crater acoustics. The build date is real now.":"கொலைகளால் அனிச்சை நிரம்பும் (தொடர் கொலைகள் அதிகம் நிரப்பும்). தோழர்கள் பின்தங்கினால் அல்லது இறந்தால், போர்த்தந்திரவாதி புதியவர்களை உன்னிடம் இறக்குவார் (வழக்கமான வலுச்சேர்ப்பை விட விலை அதிகம்). v7.2gfx வரைகலையும் ஒலியும் இணைக்கப்பட்டன: புகை மண்டலமாக வெடிப்புகள், புகை, சிதைவுகள், சுரங்கம் மற்றும் குழிகளின் ஒலியியல். உருவாக்கத் தேதி இப்போது உண்மையானது.",
"New in v7.4":"v7.4-இல் புதியவை",
"NEW IN v7.4":"v7.4-இல் புதியவை",
