"The sky is a portal: fly up and you come out on the opposite side of the meteor.":"வானம் ஒரு வாயில்: மேலே பறந்தால் எரிகல்லின் எதிர்ப்பக்கத்தில் வெளியே வருவாய்.",
"Follow the strategist's orders — XP for them is doubled and tripled.":"போர்த்தந்திரவாதியின் கட்டளைகளை நிறைவேற்று — அவற்றுக்கான அனுபவம் இரட்டிப்பாகவும் மும்மடங்காகவும் ஆகும்.",
"X — instantly switch to the squad or vehicle closest to the fight.":"X — சண்டைக்கு மிக அருகில் உள்ள படைப்பிரிவு அல்லது வாகனத்துக்கு உடனே மாறு.",
"Bullets hit hardest at medium range, 20–50 meters.":"குண்டுகள் நடுத்தர தூரத்தில், 20–50 மீட்டரில், அதிகம் தாக்கும்.",
"To win, destroy the Swarm HQ and all its key buildings.":"வெல்ல, திரளின் தலைமையகத்தையும் அதன் முக்கியக் கட்டடங்கள் அனைத்தையும் தகர்.",
