"● left finger only (auto)":"● இடது விரல் மட்டும் (தானி)",
"◎ right only (aim) — strength & radius":"◎ வலது மட்டும் (குறி) — வலிமை & ஆரம்",
"○ both fingers (free)":"○ இரு விரல்கள் (சுதந்திரம்)",
"Reset: 1 · 1.8 · 0.5":"மீட்டமை: 1 · 1.8 · 0.5",
