"sandbox · all trainings · cinema":"பயிற்சித் திடல் · அனைத்துப் பயிற்சிகள் · சினிமா",
"Career and saves stay untouched. In battle the same menu is the \"🛠 Menu\" button at the top right{0}.":"தொழில்பாதையும் சேமிப்புகளும் மாறாது. ஆட்டத்தில் அதே பட்டியல் மேல் வலது \"🛠 பட்டியல்\" பொத்தான்{0}.",
"New developer match":"புதிய உருவாக்குநர் ஆட்டம்",
"all unlocked, endless ore, instant build, arsenal":"அனைத்தும் திறந்தது, முடிவற்ற தாது, உடனடிக் கட்டுமானம், ஆயுதக் கிடங்கு",
"Trainings — all 4":"பயிற்சிகள் — 4-உம்",
"PC and phone (strategy and shooter)":"கணினி மற்றும் கைபேசி (போர்த்தந்திரம் மற்றும் துப்பாக்கி வீரர்)",
"Cinema: split screen":"சினிமா: பிரிதிரை",
"strategist bot left, shooter bot right":"இடது போர்த்தந்திர போட், வலது துப்பாக்கி வீரர் போட்",
"Cinema: everything built":"சினிமா: அனைத்தும் கட்டப்பட்டது",
"both bases built and upgraded — for footage":"இரு தளங்களும் கட்டப்பட்டு மேம்படுத்தப்பட்டன — படப்பிடிப்புக்கு",
"Cinema mode — split screen: the strategist bot on the left (top view of the base and army), the shooter bot on the right in first person. Buttons at the bottom (keys S, P): \"Split screen\" and \"★ All built\" — both bases built and upgraded for footage.":"சினிமா முறை — பிரிதிரை: இடது போர்த்தந்திர போட் (தளம் மற்றும் படையின் மேல்நோக்கு காட்சி), வலது துப்பாக்கி வீரர் போட் முதல் நபர் பார்வையில். கீழே பொத்தான்கள் (விசைகள் S, P): \"பிரிதிரை\" மற்றும் \"★ அனைத்தும் கட்டப்பட்டது\" — இரு தளங்களும் படப்பிடிப்புக்காகக் கட்டப்பட்டு மேம்படுத்தப்பட்டன.",
"The core and the tunnels through the meteor are gone — the meteor is solid, the fight is on the surface only.":"மையக்கருவும் எரிகல்லின் ஊடான சுரங்கங்களும் இனி இல்லை — எரிகல் முழுமையானது, சண்டை மேற்பரப்பில் மட்டுமே.",
"Phone: 👁 hides the HUD but keeps the jetpack, ⇆, the sticks and the objective marker. \"◎ Aim\" (right finger only) — a clearly stronger and wider magnet; the magnet for all three modes — Settings → Controls → \"Advanced\". On a vehicle gun the button says \"Get off\".":"தொலைபேசி: 👁 இடைமுகத்தை மறைக்கும், ஆனால் ஜெட்பேக், ⇆, ஜாய்ஸ்டிக்குகள், இலக்குக் குறி இருக்கும். \"◎ குறி\" (வலது விரல் மட்டும்) — தெளிவாக வலிமையான, அகலமான காந்தம்; மூன்று முறைகளுக்கான காந்த வலிமை — அமைப்புகள் → கட்டுப்பாடு → \"மேம்பட்டவை\". வாகனத் துப்பாக்கியில் பொத்தான் \"இறங்கு\" என்று காட்டும்.",
"Training: phones show phone trainings only, PCs — PC only. All 4 are in the \"🛠 Developer\" menu. Developer mode and the Arsenal are one menu now (in battle — \"🛠 Menu\" at the top right, F8 on PC).":"பயிற்சி: தொலைபேசியில் தொலைபேசிப் பயிற்சிகள் மட்டும், கணினியில் கணினிப் பயிற்சிகள் மட்டும். 4-உம் \"🛠 உருவாக்குநர்\" மெனுவில் உள்ளன. உருவாக்குநர் முறையும் ஆயுதக்கூடமும் இப்போது ஒரே மெனு (சண்டையில் — மேல் வலதில் \"🛠 மெனு\", கணினியில் F8).",
"Graphics styles \"Dendy (8-bit)\" and \"16-bit\": Settings → Graphics → \"Graphics style\" (details — the ⚙ button). If FPS is below 24 in the first ~10 s of a match, Dendy turns on by itself (still below 20 — bigger pixels, 120 lines); the \"back to normal\" notice restores normal graphics for good. Your own choice in the menu always wins.":"வரைகலைப் பாணிகள் \"Dendy (8-பிட்)\" மற்றும் \"16-பிட்\": அமைப்புகள் → வரைகலை → \"வரைகலைப் பாணி\" (விவரங்கள் — ⚙ பொத்தான்). ஆட்டத்தின் முதல் ~10 வினாடிகளில் FPS 24-க்குக் கீழ் இருந்தால் Dendy தானாக இயங்கும் (20-க்கும் கீழ் — பெரிய பிக்சல், 120 வரிகள்); \"இயல்புக்குத் திரும்பு\" அறிவிப்பு இயல்பு வரைகலையை நிரந்தரமாக மீட்கும். மெனுவில் உன் தேர்வே எப்போதும் முதன்மை.",
"3D environment models (ruins, wrecks, fortifications) — only well-rated ones, streamed on demand. Turn off: Settings → Graphics → \"New 3D environment models\".":"3D சூழல் மாதிரிகள் (இடிபாடுகள், சிதைவுகள், அரண்கள்) — நல்ல மதிப்பீடு பெற்றவை மட்டும், தேவைப்படும்போது ஏற்றப்படும். அணைக்க: அமைப்புகள் → வரைகலை → \"புதிய 3D சூழல் மாதிரிகள்\".",
"New in v7.5":"v7.5-இல் புதியவை",
"NEW IN v7.5":"v7.5-இல் புதியவை",
