"Trooper, the engineers are busy — help finish the {0}, {1} m. {2} at the site.":"போர்வீரா, பொறியாளர்கள் ஈடுபட்டுள்ளனர் — {0} கட்டி முடிக்க உதவு, {1} மீ. {2} கட்டுமான இடத்தில்.",
"Strategist order: finish the {0} ({1} m)":"போர்த்தந்திரவாதியின் கட்டளை: {0} கட்டி முடி ({1} மீ)",
"Strategist: target mark ⌖ on an enemy cluster, {0} m — artillery in 8 seconds. Stay clear!":"போர்த்தந்திரவாதி: எதிரிக் கூட்டத்தின் மீது ⌖ குறி, {0} மீ — 8 வினாடியில் பீரங்கித் தாக்குதல். அருகில் செல்லாதே!",
"MLRS \"Grad\" ×{0}: salvo at the strategist's mark":"MLRS \"கிராட்\" ×{0}: போர்த்தந்திரவாதியின் குறியில் குண்டுமழை",
"a heavy MG for 90 s":"90 வி-க்கு கனரக இயந்திரத் துப்பாக்கி",
