"Weapon cache: ":"ஆயுதப் பெட்டகம்: ",
" · grenades and mags full":" · கையெறி குண்டுகளும் குண்டுப்பெட்டிகளும் நிறைவு",
"⌖ ARTILLERY":"⌖ பீரங்கித் தாக்குதல்",
"STRATEGIST'S MARK":"போர்த்தந்திரவாதியின் குறி",
"BUILD SITE":"கட்டுமான இடம்",
"cache":"பெட்டகம்",
" m":" மீ",
