"Troopers can build: E (phone: \"Enter\") at a friendly construction site — your trooper builds it, squadmates nearby help. If the engineers are busy, the strategist asks you for help — a \"BUILD SITE\" marker.":"வீரர்கள் கட்டலாம்: E (தொலைபேசியில் \"நுழை\") நம் கட்டுமான இடத்தருகே — உன் வீரர் தானே கட்டுவார், அருகிலுள்ள சக வீரர்கள் உதவுவர். பொறியாளர்கள் பிஸியாக இருந்தால், போர்த்தந்திரவாதி உன்னிடம் உதவி கேட்பார் — \"கட்டுமான இடம்\" குறியுடன்.",
"Strategist marks: the strategist puts ⌖ on an enemy cluster near you — artillery hits it 8 s later and nearby friendly \"Grad\" MLRS fire a salvo. Your own artillery strike from strategy mode gets \"Grad\" support too.":"போர்த்தந்திரவாதியின் குறிகள்: போர்த்தந்திரவாதி உன் அருகிலுள்ள எதிரிக் கூட்டத்தில் ⌖ வைப்பார் — 8 வி கழித்து பீரங்கி தாக்கும், அருகிலுள்ள நம் MLRS \"கிராட்\"கள் குண்டுமழை பொழியும். உன் சொந்த பீரங்கித் தாக்குதலுக்கும் \"கிராட்\" ஆதரவு உண்டு.",
"Weapon caches in cargo containers and crashed satellites (📦 visible within 70 m): E — a heavy MG for 90 s, incendiary rounds or rockets, plus full grenades. Crawling: Ctrl — go prone / stand up (lower, steadier aim, but slow).":"சரக்குக் கலன்களிலும் விழுந்த செயற்கைக்கோள்களிலும் ஆயுதப் பெட்டகங்கள் (📦 70 மீ-இலிருந்து தெரியும்): E — 90 வி-க்கு கனரக இயந்திரத் துப்பாக்கி, தீக்குண்டுகள் அல்லது ராக்கெட்டுகள், கூடவே நிறைந்த கையெறி குண்டுகள். ஊர்ந்து செல்ல: Ctrl — படு / எழு (தாழ்வாக, நிலையாக, துல்லியமாக, ஆனால் மெதுவாக).",
"Anonymous statistics":"பெயரற்ற புள்ளிவிவரம்",
"no names or emails: version, device, play time — to make the game better":"பெயர்கள், மின்னஞ்சல் இல்லை: பதிப்பு, சாதனம், விளையாட்டு நேரம் — விளையாட்டை மேம்படுத்த",
"Anonymous statistics (no names or emails)":"பெயரற்ற புள்ளிவிவரம் (பெயர்கள், மின்னஞ்சல் இல்லை)",
"Split-screen cinema, no core or tunnels, troopers build, strategist marks, caches, crawling, developer menu":"திரைப்படப் பிரிதிரை, மையக்கருவும் சுரங்கங்களும் இல்லை, வீரர்கள் கட்டுதல், போர்த்தந்திரவாதியின் குறிகள், பெட்டகங்கள், ஊர்தல், உருவாக்குநர் மெனு",
"Three phone stick modes, simple strategy, vehicle gun seat, canyon terrain, squad classes, explosives":"தொலைபேசியில் மூன்று குச்சி முறைகள், எளிய உத்தி, வாகனத் துப்பாக்கி இருக்கை, பள்ளத்தாக்கு நிலப்பரப்பு, படைப்பிரிவு வகைகள், வெடிபொருள்",
"Lite mode, two-stick phone controls":"இலகு முறை, தொலைபேசியில் இருகுச்சிக் கட்டுப்பாடு",
"Milestone: outposts and HQ upgrades, cinematic misses, knockdowns":"மைல்கல்: புறக்காவல் நிலையங்கள், தலைமையக மேம்பாடுகள், திரைப்பட-பாணித் தவறுகள், வீழ்த்தல்கள்",
"Milestone: strategy + shooter in one game, v6 guns":"மைல்கல்: ஒரே ஆட்டத்தில் உத்தி + துப்பாக்கி வீரர், v6 துப்பாக்கிகள்",
"Milestone: base, squads, vehicles":"மைல்கல்: தளம், படைப்பிரிவுகள், வாகனங்கள்",
"Milestone: first armies and strategy":"மைல்கல்: முதல் படைகளும் உத்தியும்",
"Milestone: bigger meteor, raymarcher":"மைல்கல்: பெரிய எரிகல், ரேமார்ச்சர்",
"Milestone: jetpack, gravity, explorers":"மைல்கல்: ஜெட்பேக், ஈர்ப்பு, ஆய்வாளர்கள்",
