"Do not like the new version — play the one you are used to. The choice is remembered; every version has its own saves and settings (these stay safe). An old version is loaded only when chosen.":"புதிய பதிப்பு பிடிக்கவில்லையா — பழகிய பதிப்பை விளையாடு. தேர்வு நினைவில் இருக்கும்; ஒவ்வொரு பதிப்புக்கும் தனி சேமிப்புகளும் அமைப்புகளும் உண்டு (இவை அழியாது). பழைய பதிப்பு தேர்ந்தால் மட்டுமே ஏற்றப்படும்.",
