"infantry +10% speed, jetpacks +20%":"காலாட்படை +10% வேகம், ஜெட்பேக்குகள் +20%",
"drones −25% cost, limit ×1.5; cannons & rails +20%":"ட்ரோன்கள் −25% விலை, வரம்பு ×1.5; பீரங்கிகளும் தண்டவாளத் துப்பாக்கிகளும் +20%",
"unique: \"Drone pack\", \"Phase jetpacks\"":"தனித்துவம்: \"ட்ரோன் கூட்டம்\", \"கட்ட ஜெட்பேக்குகள்\"",
"infantry −8% toughness, lighter vehicles":"காலாட்படை −8% உறுதி, இலகுவான வாகனங்கள்",
