"The HUD stays sharp; the Dendy style is also faster (fewer pixels).":"இடைமுகம் தெளிவாகவே இருக்கும்; Dendy பாணி வேகமானதும் கூட (குறைந்த பிக்சல்கள்).",
"That is not the sky above you. It is a portal to the enemy.":"உன் தலைக்கு மேலே இருப்பது வானம் அல்ல. அது எதிரியிடம் செல்லும் வாயில்.",
"tap to skip":"தட்டு — தவிர்",
