"to battle":"சண்டைக்கு",
"You are on a turret — fire at the Swarm":"நீ கோபுரத்தில் இருக்கிறாய் — ஸ்வார்மைத் தாக்கு",
"get off":"இறங்கு",
"Low armor — get behind cover":"கவசம் குறைவு — மறைவுக்குப் பின் செல்",
"you self-repair out of combat, a medic is faster":"சண்டைக்கு வெளியே தானே பழுதாகும், மருத்துவர் வேகமானவர்",
