"The Swarm is attacking — hold the line":"ஸ்வார்ம் தாக்குகிறது — அரணைக் காத்துக்கொள்",
"unit closer to the fight":"சண்டைக்கு அருகில் வீரர்",
"Side task nearby":"அருகில் துணைப் பணி",
