"Captures · orders":"கைப்பற்றல்கள் · கட்டளைகள்",
"you":"நீ",
"BEST SQUAD":"சிறந்த படைப்பிரிவு",
"Stats count from the moment the save was loaded.":"புள்ளிவிவரம் சேமிப்பு ஏற்றிய தருணத்திலிருந்து கணக்கிடப்படும்.",
"Game link":"விளையாட்டு இணைப்பு",
"Play again":"மீண்டும் ஆடு",
"KILLS":"அழிப்புகள்",
"STREAK":"தொடர்",
"me":"நான்",
"free in your browser · PC & phone":"உலாவியில் இலவசம் · கணினி & தொலைபேசி",
