"shurikens":"ஷுரிகன்கள்",
"teleport":"டெலிபோர்ட்",
"posture":"நிலை",
"looking for an enemy zone":"எதிரி மண்டலம் தேடுகிறேன்",
"LMB — strike (hold — heavy) · RMB — block · Shift — blink · Q — shurikens · G — teleport":"இடது சொடுக்கு — தாக்கு (பிடி — கனத்தது) · வலது சொடுக்கு — தடு · Shift — மின்னல் தாவல் · Q — ஷுரிகன்கள் · G — டெலிபோர்ட்",
"Block":"தடு",
"Blink":"தாவல்",
