"Radio Portal Meteor: 100+ tracks by EDMITRY right in the game — the 📻 button (PC: key 5, [ ] — track). Music streams on demand and does not bloat the game; volume and autostart in Settings, plus a \"Listen on Spotify\" link.":"Portal Meteor வானொலி: EDMITRY-யின் 100+ பாடல்கள் விளையாட்டிலேயே — 📻 பொத்தான் (PC: 5 விசை, [ ] — பாடல்). இசை தேவைக்கேற்ப இணையத்திலிருந்து வருகிறது, விளையாட்டு கனக்காது; ஒலியளவு, தானியங்கித் தொடக்கம் அமைப்புகளில், மேலும் \"Spotify-இல் கேள்\" இணைப்பு.",
