"on air":"ஒலிபரப்பில்",
"paused":"இடைநிறுத்தம்",
"no signal — silent":"சமிக்ஞை இல்லை — அமைதி",
"tap ▶":"▶ தட்டு",
"RADIO PORTAL METEOR":"PORTAL METEOR வானொலி",
"Now playing":"இப்போது ஒலிப்பது",
"Listen on Spotify":"Spotify-இல் கேள்",
"RADIO":"வானொலி",
"on/off":"இயக்கு/நிறுத்து",
"track":"பாடல்",
"Radio":"வானொலி",
"Radio Portal Meteor on/off ([ ] — track, Shift+[ ] — volume)":"Portal Meteor வானொலி இயக்கு/நிறுத்து ([ ] — பாடல், Shift+[ ] — ஒலியளவு)",
"📻 on the right — Radio Portal Meteor: music by EDMITRY while you fight.":"வலப்புறம் 📻 — Portal Meteor வானொலி: சண்டையின்போது EDMITRY-யின் இசை.",
"{0} — Radio Portal Meteor: music by EDMITRY while you fight. [ ] — track.":"{0} — Portal Meteor வானொலி: சண்டையின்போது EDMITRY-யின் இசை. [ ] — பாடல்.",
"Radio Portal Meteor (EDMITRY): volume":"Portal Meteor வானொலி (EDMITRY): ஒலியளவு",
"Radio: start by itself in battle":"வானொலி: சண்டையில் தானாகத் தொடங்கு",
"Robo-ninja: a cyborg with a katana. Unlocked at the Barracks with the \"Shadow Protocol\" research (needs a Mech Factory). Teleports into enemy zones by herself, cuts enemies apart (no blood — sparks), dashes, shuriken, duels with the enemy ninja. Possess her — AUTO mode or manual control (own buttons on the phone).":"ரோபோ-நிஞ்சா: கடானா ஏந்திய சைபோர்க். படைவீட்டில் \"நிழல் நெறிமுறை\" ஆய்வால் திறக்கும் (இயந்திர ஆலை தேவை). தானாகவே எதிரி மண்டலங்களுக்கு டெலிபோர்ட் ஆகி, எதிரிகளைத் துண்டாக வெட்டுகிறாள் (ரத்தம் இல்லை — தீப்பொறிகள்), தாவல்கள், ஷுரிகன், எதிரி நிஞ்சாவுடன் சண்டை. அவளை ஆட்கொள் — AUTO முறை அல்லது கைமுறைக் கட்டுப்பாடு (தொலைபேசியில் தனிப் பொத்தான்கள்).",
"Radio Portal Meteor: 103 EDMITRY tracks right in the game. Key 5 (rebindable), on the phone — ☰ → Settings → Sound. Volume and \"auto-play in battle\" in the settings; the music ducks under explosions and radio voice.":"Portal Meteor வானொலி: EDMITRY-யின் 103 பாடல்கள் விளையாட்டிலேயே. 5 விசை (மாற்றியமைக்கலாம்), தொலைபேசியில் — ☰ → அமைப்புகள் → ஒலி. ஒலியளவு, \"சண்டையில் தானாகத் தொடங்கு\" அமைப்புகளில்; வெடிப்புகளிலும் ரேடியோ குரலிலும் இசை தாழும்.",
"New languages: Uzbek and Tajik — complete; Chinese, Spanish, Portuguese — partial. New language selector in the menu next to \"New match\".":"புதிய மொழிகள்: உஸ்பெக், தாஜிக் — முழுமை; சீனம், ஸ்பானிஷ், போர்ச்சுகீசியம் — பகுதி. மெனுவில் \"புதிய ஆட்டம்\" அருகே புதிய மொழித் தேர்வு.",
"Phone: \"hide icons\" 👁 gathers the remaining buttons into a tidy column at the right edge; portrait no longer overlaps; iPhone — the game no longer fights Safari gestures, and \"Share → Add to Home Screen\" launches it full screen.":"தொலைபேசி: \"சின்னங்களை மறை\" 👁 மீதமுள்ள பொத்தான்களை வலது ஓரத்தில் நேர்த்தியான வரிசையாகத் திரட்டுகிறது; நிமிர்வுத் தோற்றம் இனி முட்டாது; iPhone — விளையாட்டு Safari சைகைகளுடன் மோதாது, \"பகிர் → முகப்புத் திரையில் சேர்\" முழுத்திரையில் தொடங்கும்.",
"From v7.8.1: ☰ corner menu (pause, restart, training, graphics), no auto-Dendy, ✋ action button on the phone. v7.8.1 and v7.8 stay in the \"🕘 Game version\" menu.":"v7.8.1-இலிருந்து: மூலையில் ☰ மெனு (இடைநிறுத்தம், மறுதொடக்கம், பயிற்சி, வரைகலை), தானியங்கி Dendy இல்லை, தொலைபேசியில் ✋ செயல் பொத்தான். v7.8.1, v7.8 ஆகியவை \"🕘 விளையாட்டுப் பதிப்பு\" மெனுவில் உள்ளன.",
"Robo-ninja, EDMITRY radio, Uzbek and Tajik, phone and iPhone UX":"ரோபோ-நிஞ்சா, EDMITRY வானொலி, உஸ்பெக், தாஜிக், தொலைபேசி மற்றும் iPhone வசதி",
