"The new squad is selected — tap the red \"ATTACK\" marker.":"புதிய படைப்பிரிவு தேர்வானது — சிவப்பு \"தாக்கு\" குறியைத் தட்டு.",
"💥 Methane exploded! The fog over the lake burned away":"💥 மீத்தேன் வெடித்தது! ஏரியின் மேல் மூடுபனி எரிந்தது",
