"♨ AIR RAID! Swarm napalm — get out of the red circle!":"♨ வான்தாக்குதல்! திரளின் நேபாம் — சிவப்பு வட்டத்திலிருந்து வெளியேறு!",
"Air raid! Bomber overhead!":"வான்தாக்குதல்! தலைக்கு மேல் குண்டுவீச்சு விமானம்!",
"Carpet bombing":"தொடர் குண்டுவீச்சு",
"A bomber drops 10 bombs along an 80 m strip, approaching from your base (in battle — along your view). After 3.5 s, leaves craters.":"குண்டுவீச்சு விமானம் உங்கள் தளத்திலிருந்து (போரில் — உங்கள் பார்வையின் வழியே) வந்து 80 மீ பட்டையில் 10 குண்டுகள் போடும். 3.5 வி கழித்து, குழிகளை விடும்.",
"Napalm":"நேபாம்",
"A 12 m fire zone burns for 9 seconds: damage over time, suppression, smoke. After 2.5 s. Ignites methane.":"12 மீ தீ மண்டலம் 9 விநாடிகள் எரியும்: தொடர் சேதம், அடக்குதல், புகை. 2.5 வி கழித்து. மீத்தேனைப் பற்ற வைக்கும்.",
"Bomber: target received, inbound!":"குண்டுவீச்சு விமானம்: இலக்கு பெற்றோம், வருகிறோம்!",
"Attack jet: napalm inbound!":"தாக்குதல் விமானம்: நேபாம் வருகிறது!",
"Support: crate, recon, \"Grad\", artillery, carpet bombing, napalm (then 1–6)":"ஆதரவு: பெட்டி, உளவு, \"கிராட்\", பீரங்கித் தாக்குதல், தொடர் குண்டுவீச்சு, நேபாம் (பின் 1–6)",
"☄ Meteor shower in 10 s — take cover: the rock hangar, under a ridge!":"☄ 10 வி-இல் எரிகல் மழை — மறைவிடம் செல்: பாறை ஹேங்கர், மேடு அடியில்!",
"Warning: meteor shower! Everyone take cover":"கவனம்: எரிகல் மழை! அனைவரும் மறைவிடம் செல்லுங்கள்",
"Meteor shower in ":"எரிகல் மழை ",
" s — take cover":" வி-இல் — மறைவிடம் செல்",
"Concrete barrier":"கான்கிரீட் தடுப்பு",
"Consortium. 7 m wall section: stops bullets, shells and vehicles. Chain them (Shift+click).":"Consortium. 7 மீ சுவர்ப் பகுதி: தோட்டாக்கள், குண்டுகள், வாகனங்களைத் தடுக்கும். சங்கிலியாக அமை (Shift+சொடுக்கு).",
"Repair post":"பழுதுபார்ப்பு நிலையம்",
"Consortium. Repairs vehicles, buildings and infantry within 26 m.":"Consortium. 26 மீ சுற்றளவில் வாகனங்கள், கட்டடங்கள், காலாட்படையைச் சரிசெய்யும்.",
"Tunnel burrow":"சுரங்கப் புற்று",
"Swarm. Tunnel entrance: then \"Dig the exit\" to a point up to 220 m away — infantry travels underground.":"திரள். சுரங்க நுழைவு: பின் 220 மீ வரை ஒரு புள்ளிக்கு \"வெளியேற்றம் தோண்டு\" — காலாட்படை நிலத்தடியே செல்லும்.",
"Tunnel exit":"சுரங்க வெளியேற்றம்",
"Swarm. Tunnel exit. Destroy it and the tunnel collapses.":"திரள். சுரங்க வெளியேற்றம். இதை அழித்தால் சுரங்கம் இடிந்துவிடும்.",
"Appears by itself when the tunnel breaks through":"சுரங்கம் துளைத்ததும் தானாகத் தோன்றும்",
"cover":"மறைவிடம்",
