"digging the exit":"வெளியேற்றம் தோண்டுகிறது",
"tunnel open":"சுரங்கம் திறந்தது",
"no exit yet":"வெளியேற்றம் இன்னும் இல்லை",
"Too far: {0} m (max {1} m)":"மிகத் தொலைவு: {0} மீ (அதிகபட்சம் {1} மீ)",
