"A shaft is nearby":"அருகில் சுரங்கத் தண்டு உள்ளது",
"Tunnel open! Select squads → \"Into tunnel\" on the card":"சுரங்கம் திறந்தது! படைப்பிரிவுகளைத் தேர்ந்து அட்டையில் \"சுரங்கத்துக்குள்\"",
"Tunnel open! Select squads → \"Into tunnel\" on the card or RMB the burrow":"சுரங்கம் திறந்தது! படைப்பிரிவுகளைத் தேர்ந்து அட்டையில் \"சுரங்கத்துக்குள்\" அல்லது புற்றில் வலது சொடுக்கு",
"The tunnel is through. Ready to move":"சுரங்கம் துளைத்தது. நகரத் தயார்",
