"⚠ Rumbling underground: the Swarm is digging a tunnel! Breakthrough in ~10 s — be ready":"⚠ நிலத்தடியில் இரைச்சல்: திரள் சுரங்கம் தோண்டுகிறது! ~10 வி-இல் ஊடுருவல் — தயாராக இரு",
"Warning! Digging heard. The enemy is tunnelling":"கவனம்! தோண்டும் ஒலி கேட்கிறது. எதிரி சுரங்கம் தோண்டுகிறான்",
"Needs a Tunnel burrow — builders make it":"சுரங்கப் புற்று தேவை — கட்டுநர்கள் கட்டுவர்",
