"LMB — exit point (up to {0} m from the burrow), RMB — cancel":"LMB — வெளியேற்றப் புள்ளி (புற்றிலிருந்து {0} மீ வரை), RMB — ரத்து",
"Dig the exit first":"முதலில் வெளியேற்றம் தோண்டு",
