"no squads within 70 m of the burrow — select squads and RMB/tap the burrow":"புற்றின் 70 மீ-இல் படைப்பிரிவுகள் இல்லை — படைப்பிரிவுகளைத் தேர்ந்து RMB/தட்டு",
"Digging: {0} s. The enemy will hear it 10 s before breakthrough":"தோண்டுகிறது: {0} வி. ஊடுருவலுக்கு 10 வி முன் எதிரி ஒலி கேட்பான்",
"Exit · {0} m · {1} s":"வெளியேற்றம் · {0} மீ · {1} வி",
"Dig the exit":"வெளியேற்றம் தோண்டு",
"Swarm. Pick a point up to 220 m away — the exit breaks through in 24 s. 10 s before, the enemy hears rumbling and sees dust.":"திரள். 220 மீ வரை ஒரு புள்ளியைத் தேர்ந்தெடு — வெளியேற்றம் 24 வி-இல் துளைக்கும். 10 வி முன் எதிரி இரைச்சலும் புழுதியும் காண்பான்.",
"Squads into the tunnel":"படைப்பிரிவுகள் — சுரங்கத்துக்குள்",
"Swarm. Squads within 70 m of the burrow (and selected ones) go through the tunnel. Or select squads and RMB/tap the burrow.":"திரள். புற்றின் 70 மீ-இல் உள்ள (தேர்ந்த) படைப்பிரிவுகள் சுரங்கம் வழியே மறுமுனையில் வெளியேறும். அல்லது படைப்பிரிவுகளைத் தேர்ந்து புற்றில் RMB/தட்டு.",
"Swarm only":"திரள் மட்டும்",
"Needs a Tunnel burrow":"சுரங்கப் புற்று தேவை",
"Still being built":"இன்னும் கட்டப்படுகிறது",
"Exit already open":"வெளியேற்றம் ஏற்கனவே திறந்துள்ளது",
"No exit yet — \"Dig the exit\" in the burrow panel":"வெளியேற்றம் இன்னும் இல்லை — புற்றின் பலகத்தில் \"வெளியேற்றம் தோண்டு\"",
"Too close to the HQ or a point — no digging here":"தலைமையகம் அல்லது புள்ளிக்கு மிக அருகில் — இங்கு தோண்ட முடியாது",
"Rocks in the way":"பாறைகள் தடுக்கின்றன",
"Selected squads go into the nearest open tunnel and come out at the other end":"தேர்ந்த படைப்பிரிவுகள் அருகிலுள்ள திறந்த சுரங்கத்துக்குள் சென்று மறுமுனையில் வெளியேறும்",
"Into tunnel":"சுரங்கப் புற்று தேவை",
"\"Bastion\"":"\"கொத்தளம்\"",
