"Consortium. From 12:00. Builds the super-heavy tank \"Bastion\" (one per army).":"கூட்டமைப்பு. போரின் 12:00-இலிருந்து. இங்கு சூப்பர் கனரகப் பீரங்கி வண்டி \"கொத்தளம்\" செய்யப்படும் (ஓர் அணிக்கு ஒன்று).",
"Incubator":"அடைகாப்பகம்",
"Swarm. From 12:00. Grows the \"Reaper\" walker (one per army).":"திரள். 12:00-இலிருந்து. நடைக்கலன் \"அறுவடையாளன்\" இங்கு வளரும் (ஓர் அணிக்கு ஒன்று).",
"Super-heavy tank \"Bastion\"":"சூப்பர் கனரகப் பீரங்கி வண்டி \"கொத்தளம்\"",
"Consortium. Boss: 15000 hull, cannon, 2 MGs, rockets. Very slow. Weak spot — the rear. One per army.":"கூட்டமைப்பு. தலைவன்: 15000 உடல்வலிமை, பீரங்கி, 2 இயந்திரத் துப்பாக்கிகள், ராக்கெட்டுகள். மிக மெதுவானது. பலவீனம் — பின்புறம். ஓர் அணிக்கு ஒன்று.",
"Walker \"Reaper\"":"நடைக்கலன் \"அறுவடையாளன்\"",
"Swarm. Boss: 12500 hull, distortion beam, stomp. Steps over barriers. Weak spot — the core underneath. One per army.":"திரள். தலைவன்: 12500 உடல்வலிமை, சிதைவுக் கதிர், மிதிப்பு. தடுப்புகளைத் தாண்டும். பலவீனம் — வயிற்றின் கீழ் உள்ள மையக்கரு. ஓர் அணிக்கு ஒன்று.",
"Limit: 1 per army":"வரம்பு: அணிக்கு 1",
