"Strip: ⟳ to rotate, or drag from the target along the run":"பட்டை: ⟳ — சுழற்று, அல்லது இலக்கிலிருந்து தாக்குதல் திசையில் விரலால் இழு",
"Strip: mouse wheel or R to rotate, or drag from the target along the run":"பட்டை: சுட்டிச் சக்கரம் அல்லது R — சுழற்று, அல்லது இலக்கிலிருந்து தாக்குதல் திசையில் சுட்டியால் இழு",
