"Swarm. Squads within 70 m of the burrow (and selected ones), plus selected light/medium vehicles (Jackal, Hammer, Grad), go through the tunnel. Or: select and RMB/tap the burrow.":"திரள். புற்றிலிருந்து 70 மீ-க்குள் உள்ள படைப்பிரிவுகள் (மற்றும் தேர்ந்தவை), தேர்ந்த இலகு/நடுத்தர வாகனங்கள் (குள்ளநரி, சம்மட்டி, கிராட்) சுரங்கம் வழியாகச் சென்று மறுமுனையில் வெளியேறும். அல்லது: தேர்ந்து புற்றை RMB/தட்டு.",
"Air strikes":"வான்தாக்குதல்கள்",
"Carpet bombing and napalm: aiming, rotating the strip, enemy warning, calling from battle":"கம்பளக் குண்டுவீச்சு மற்றும் நேப்பாம்: குறிவைத்தல், பட்டையைச் சுழற்றுதல், எதிரி எச்சரிக்கை, போரிலிருந்து அழைத்தல்",
"Terrain and lakes":"நிலவடிவமும் ஏரிகளும்",
"Lava burns, ice slides, methane explodes from fire, the rock hangar is cover":"எரிமலைக்குழம்பு சுடும், பனி வழுக்கும், மீத்தேன் நெருப்பில் வெடிக்கும், பாறை வானூர்திக் கூடம் ஒரு மறைவிடம்",
"Swarm: tunnels":"திரள்: சுரங்கங்கள்",
"You play the Swarm: tunnel burrow, exit up to 220 m, dust warning, squads and vehicles through":"நீ திரளாக விளையாடுகிறாய்: சுரங்கப் புற்று, 220 மீ வரை வெளிவழி, புழுதி எச்சரிக்கை, படைப்பிரிவுகளும் வாகனங்களும் சுரங்கத்துக்குள்",
"Consortium: fortifications":"கூட்டமைப்பு: அரண்கள்",
"You play the Consortium: barrier chains, repair post, field repair by builders":"நீ கூட்டமைப்பாக விளையாடுகிறாய்: தடுப்புச் சங்கிலி, பழுதுபார்ப்பு நிலையம், கட்டுநர்களின் களப் பழுதுபார்ப்பு",
"Bosses":"முதன்மை எதிரிகள்",
"\"Bastion\" and \"Reaper\": from 12:00 (skipped here), plant, assembly, orders, weak spots, possession":"\"கொத்தளம்\" மற்றும் \"அறுவடையாளன்\": 12:00 முதல் (இங்கே தவிர்க்கப்பட்டது), ஆலை, உருவாக்கம், கட்டளைகள், பலவீனப் புள்ளிகள், கட்டுப்படுத்துதல்",
