"Burrow under construction":"புற்று கட்டப்படுகிறது",
"Digging: the enemy hears it":"சுரங்கம் தோண்டல்: எதிரிக்குக் கேட்கும்",
"Squad into the tunnel":"படைப்பிரிவு — சுரங்கத்துக்குள்",
