"Enemy sabotage: our turrets are down for 2 min":"எதிரியின் நாசவேலை: நம் டரெட்டுகள் 2 நிமிடம் செயலிழப்பு",
"Enemy took the relay: they see us for 60 s":"எதிரி ரிலேயைப் பிடித்தான்: 60 வி நம்மைப் பார்க்கிறான்",
"Sabotage! Our turrets are without power for two minutes.":"நாசவேலை! நம் டரெட்டுகளுக்கு இரண்டு நிமிடம் மின்சாரம் இல்லை.",
