"here, a gun from the trunk — MG for 90 s":"இந்தா, வாகனப் பெட்டியிலிருந்து துப்பாக்கி — 90 வி இயந்திரத் துப்பாக்கி",
"a pod is launched from the base — a trooper for your squad":"தளத்திலிருந்து கேப்சூல் வருகிறது — உன் படைக்கு ஒரு வீரர்",
"a satellite will cover you for 20 s":"செயற்கைக்கோள் 20 வி உனக்குக் காப்பு தரும்",
"+2 CP for HQ":"தலைமையகத்துக்கு +2 கபு",
"Pod from the base: {0} joins the squad":"தளத்திலிருந்து கேப்சூல்: {0} படையில் இணைந்தான்",
"Living world: your units ask for help, heroes give quests. Card on the right — ✕ to dismiss.":"உயிர்ப்புள்ள உலகம்: நம்மவர் உதவி கேட்பார்கள், வீரர்கள் பணி தருவார்கள். வலதுபுற அட்டை — ✕ நீக்க.",
"Living world: your units ask for help, heroes give quests. Y — accept, N — decline.":"உயிர்ப்புள்ள உலகம்: நம்மவர் உதவி கேட்பார்கள், வீரர்கள் பணி தருவார்கள். Y — ஏற்க, N — மறுக்க.",
