"SABOTAGE":"நாசவேலை",
"Living world: requests, hero quests, breakthrough ops":"உயிர்ப்புள்ள உலகம்: நம்மவர் வேண்டுகோள், வீரர் பணிகள், போரில் திருப்பம்",
"Living world":"உயிர்ப்புள்ள உலகம்",
"Your units ask for help and reward you, heroes give quests, a stalled front is broken by an op":"நம்மவர் உதவி கேட்டு வெகுமதி தருவார்கள், வீரர்கள் பணி தருவார்கள், தேங்கிய முன்னணியை ஒரு நடவடிக்கையால் உடைக்கலாம்",
"A request":"நம்மவர் வேண்டுகோள்",
"Breakthrough":"போரில் திருப்பம்",
"Your units sometimes ask for help: a radio call, a REQUEST card and a ✋ marker. A squad is pinned — destroy the enemies near it. Reward: a trooper by pod from the base, a gun from a buggy trunk, the gunner seat or orbital cover. Not now — ✕ or just ignore it.":"நம்மவர் சில சமயம் உதவி கேட்பார்கள்: வானொலியில் குரல், “வேண்டுகோள்” அட்டை, ✋ குறியீடு. ஒரு குழு முடக்கப்பட்டது — அதன் அருகிலுள்ள எதிரிகளை அழி. வெகுமதி: தளத்திலிருந்து கேப்சூல் வழியாக ஒரு வீரர், பகியின் பெட்டியிலிருந்து துப்பாக்கி, துப்பாக்கி வீரர் இருக்கை அல்லது சுற்றுப்பாதைக் காப்பு. வேண்டாமெனில் — ✕ அல்லது புறக்கணி.",
"Veteran scout \"Owl\" offers a quest. Y — accept (N — decline). Go to the ★ marker, clear the guards and stay by the pilot for 3 s — he joins your squad.":"மூத்த உளவாளி “ஆந்தை” ஒரு பணி தருகிறார். Y — ஏற்க (N — மறுக்க). ★ குறியிடத்துக்குச் செல், காவலர்களை அகற்று, விமானி அருகே 3 வி நில் — அவன் உன் படையில் இணைவான்.",
"The front is stuck — HQ offers a breakthrough. Y — accept. Hold the relay for 8 s with no foes near: the enemy map is revealed for 60 s. The generator — enemy turrets go silent for 2 min. In Strategist — \"Assign a squad\". The enemy can do it too: watch for ⚠.":"முன்னணி தேங்கிவிட்டது — தலைமையகம் ஒரு திருப்பத்தை முன்மொழிகிறது. Y — ஏற்க. ஒளிபரப்பு நிலையத்தை அருகில் எதிரியின்றி 8 வி தக்கவை: எதிரி வரைபடம் 60 வி தெரியும். மின்னாக்கி — எதிரிக் கோபுரங்கள் 2 நிமிடம் அமைதி. போர்த்தந்திரவாதியில் — “படைப்பிரிவுக்கு வழங்கு”. எதிரியும் இதைச் செய்வான்: ⚠ ஐக் கவனி.",
"Your units ask for help: a REQUEST card and a ✋ marker. Destroy the enemies near the pinned squad — get a reward. ✕ — skip.":"நம்மவர் உதவி கேட்கிறார்கள்: “வேண்டுகோள்” அட்டை, ✋ குறியீடு. முடங்கிய படைப்பிரிவின் அருகிலுள்ள எதிரிகளை அழித்தால் வெகுமதி கிடைக்கும். ✕ — தவிர்.",
"Hero \"Owl\" offers a quest — tap \"Accept\". Go to ★, clear the guards, stay by the pilot.":"வீரர் “ஆந்தை” பணி தருகிறார் — “ஏற்றுக்கொள்” தட்டு. ★ க்குச் செல், காவலர்களை அகற்று, விமானி அருகே நில்.",
"The front is stuck — tap \"Accept\" and hold the relay for 8 s: the enemy map opens for a minute.":"முன்னணி தேங்கிவிட்டது — “ஏற்றுக்கொள்” தட்டி ஒளிபரப்பு நிலையத்தை 8 வி தக்கவை: எதிரி வரைபடம் ஒரு நிமிடம் திறக்கும்.",
"Pod redeploy from the base: {0} m — through the sky portal":"தளத்திலிருந்து கலத்தில் இடமாற்றம்: {0} மீ — வான்வாயில் வழியாக",
"Pod away from the base! Hold on — exit over the target.":"தளத்திலிருந்து கலம் புறப்பட்டது! பிடித்துக்கொள்ளுங்கள் — இலக்கின் மேலே வெளியேறுவோம்.",
"Landed at the objective!":"இலக்கருகே இறங்கினோம்!",
