"Lefty's convoy is ready: two Jackals. Stay close — they wait for you":"“இடதுகையன்” குழு தயார்: இரண்டு “குள்ளநரி”. அருகிலேயே இரு — உனக்காகக் காத்திருக்கின்றன",
