"Ambush! Cover the Jackals!":"பதுங்கித் தாக்குதல்! \"குள்ளநரி\"களுக்குப் பாதுகாப்பு கொடு!",
"the convoy made it ({0} of 2)! +2 CP, +150 ore, the Jackals are yours":"கான்வாய் வந்து சேர்ந்தது (2-இல் {0})! +2 கபு, +150 தாது, \"குள்ளநரி\"கள் உன்னுடையவை",
