"Button remapping comes in a later version. Keyboard, mouse and touch work as before; hints switch to the gamepad by themselves while you use it.":"பொத்தான் மறுஒதுக்கீடு அடுத்த பதிப்பில் வரும். விசைப்பலகை, மவுஸ், தொடுதிரை முன்பு போலவே வேலை செய்யும்; நீ கேம்பேட் பயன்படுத்தும்போது குறிப்புகள் தாமாகவே அதற்கு மாறும்.",
