"1. Start a screen recording with your voice (PC — OBS, phone — the built-in screen recorder with mic) and turn on Feedback mode here.":"1. உங்கள் குரலுடன் திரைப் பதிவைத் தொடங்குங்கள் (PC — OBS, ஃபோன் — மைக்குடன் உள்ளமைந்த திரைப் பதிவு), இங்கே கருத்து முறையை இயக்குங்கள்.",
"2. Play and think aloud: what is unclear, annoying, fun. The corner shows version, time and FPS — they match the recording to the notes.":"2. விளையாடிக்கொண்டே சத்தமாகச் சிந்தியுங்கள்: எது புரியவில்லை, எது எரிச்சலூட்டுகிறது, எது பிடிக்கிறது. மூலையில் பதிப்பு, நேரம், FPS தெரியும் — அவை பதிவையும் குறிப்புகளையும் பொருத்த உதவும்.",
"3. When something matters — take a note: PC ":"3. ஏதாவது முக்கியம் என்றால் — குறிப்பு எடுங்கள்: PC ",
" (press ":" (எழுதிச் சேர்க்க மீண்டும் அழுத்துங்கள்: ",
