"4. After playing: Download all and send the file to Claude together with the recording.":"4. விளையாடிய பிறகு: «அனைத்தையும் பதிவிறக்கு» அழுத்தி, கோப்பைப் பதிவுடன் சேர்த்து Claude க்கு அனுப்புங்கள்.",
