"Want to command the army?":"படையை வழிநடத்த விரும்புகிறீர்களா?",
"Unlock the Strategist mode: look from above and give orders to the whole army.":"Strategist முறையைத் திறக்கவும்: மேலிருந்து பார்த்து முழுப் படைக்கும் கட்டளையிடுங்கள்.",
"Want to lead one squad?":"ஒரு படைப்பிரிவை வழிநடத்த விரும்புகிறீர்களா?",
"Unlock the Commander mode: camera over a squad, tap where to go.":"Commander முறையைத் திறக்கவும்: கேமரா படைப்பிரிவின் மேல், எங்கே செல்ல வேண்டுமென்று தட்டுங்கள்.",
"Yes":"ஆம்",
"Later":"பிறகு",
"You run and shoot yourself. That is how you have played so far.":"நீங்களே ஓடிச் சுடுகிறீர்கள். இதுவரை இப்படித்தான் விளையாடினீர்கள்.",
"Look from above and command the whole army: build the base, send squads. The army also fights on its own.":"மேலிருந்து பார்த்து முழுப் படைக்கும் கட்டளையிடுகிறீர்கள்: தளம் கட்டுங்கள், படைப்பிரிவுகளை அனுப்புங்கள். நீங்கள் இல்லாமலும் படை தானாகப் போராடும்.",
"You lead one squad: the camera is above it, tap the ground to move.":"ஒரு படைப்பிரிவை வழிநடத்துகிறீர்கள்: கேமரா அதன் மேல் இருக்கும், செல்ல நிலத்தைத் தட்டுங்கள்.",
"The mode button is at the top right: tap for the next mode.":"முறைப் பொத்தான் மேலே வலப்புறம்: அடுத்த முறைக்கு தட்டுங்கள்.",
